contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val, address _log) public payable {
        uint before = c.MinSum(); if (__ESBMC_reverted()) return;
        bool firstReverted;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }
        require(!firstReverted, "SetMinSum unexpectedly reverted");
        bool secondReverted;
        c.SetMinSum(before); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }
        assert(!secondReverted || c.MinSum() == _val);
    }

    receive() external payable {}
}

